"use strict";(self.webpackChunkhn_cho_sh=self.webpackChunkhn_cho_sh||[]).push([[6381],{3331:(e,a,o)=>{o.d(a,{R:()=>t,x:()=>n});var s=o(36672);const i={},r=s.createContext(i);function t(e){const a=s.useContext(r);return s.useMemo((function(){return"function"==typeof e?e(a):{...a,...e}}),[a,e])}function n(e){let a;return a=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:t(e.components),s.createElement(r.Provider,{value:a},e.children)}},52053:(e,a,o)=>{o.r(a),o.d(a,{assets:()=>d,contentTitle:()=>n,default:()=>l,frontMatter:()=>t,metadata:()=>s,toc:()=>c});const s=JSON.parse('{"id":"2023/04/17","title":"2023-04-17","description":"De-Stressing Booking.com","source":"@site/i18n/pt/docusaurus-plugin-content-docs/current/2023/04/17.md","sourceDirName":"2023/04","slug":"/2023/04/17","permalink":"/pt/2023/04/17","draft":false,"unlisted":false,"editUrl":"https://github.com/anaclumos/heimdall/blob/main/i18n/pt/docusaurus-plugin-content-docs//current/2023/04/17.md","tags":[],"version":"current","frontMatter":{"localized_date":"17 de abril de 2023","top_news":"De-Stressing Booking.com"},"sidebar":"defaultSidebar","previous":{"title":"2023-04-18","permalink":"/pt/2023/04/18"},"next":{"title":"2023-04-16","permalink":"/pt/2023/04/16"}}');var i=o(23420),r=o(3331);const t={localized_date:"17 de abril de 2023",top_news:"De-Stressing Booking.com"},n="2023-04-17",d={},c=[{value:"De-Stressing Booking.com",id:"de-stressing-bookingcom",level:2},{value:"Usei Difus\xe3o Est\xe1vel e Dreambooth para criar um retrato art\xedstico do meu c\xe3o",id:"usei-difus\xe3o-est\xe1vel-e-dreambooth-para-criar-um-retrato-art\xedstico-do-meu-c\xe3o",level:2},{value:"AT&amp;T A modela\xe7\xe3o do tr\xe1fego sem fios, aparentemente tornando alguns websites inutiliz\xe1veis",id:"att-a-modela\xe7\xe3o-do-tr\xe1fego-sem-fios-aparentemente-tornando-alguns-websites-inutiliz\xe1veis",level:2},{value:"Futuros Blues - Emily&#39;s Cowboy Bebop Page (1999)",id:"futuros-blues---emilys-cowboy-bebop-page-1999",level:2},{value:"Lavadora de lou\xe7a Salm\xe3o",id:"lavadora-de-lou\xe7a-salm\xe3o",level:2},{value:"Pico3D: Open World 3D Game Engine for the PicoSystem (RP2040 Microcontrolador)",id:"pico3d-open-world-3d-game-engine-for-the-picosystem-rp2040-microcontrolador",level:2},{value:"Wayback: Servi\xe7o de arquivo auto-hospedado integrado com o Arquivo da Internet",id:"wayback-servi\xe7o-de-arquivo-auto-hospedado-integrado-com-o-arquivo-da-internet",level:2},{value:"A biblioteca de composi\xe7\xe3o matem\xe1tica mais r\xe1pida para a web",id:"a-biblioteca-de-composi\xe7\xe3o-matem\xe1tica-mais-r\xe1pida-para-a-web",level:2},{value:"&#39;\xc1lgebra para ningu\xe9m&#39; falha em S\xe3o Francisco",id:"\xe1lgebra-para-ningu\xe9m-falha-em-s\xe3o-francisco",level:2},{value:"FSF Slams Google over Droppping JPEG-XL em Cromo",id:"fsf-slams-google-over-droppping-jpeg-xl-em-cromo",level:2}];function m(e){const a={a:"a",h1:"h1",h2:"h2",header:"header",p:"p",...(0,r.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(a.header,{children:(0,i.jsx)(a.h1,{id:"2023-04-17",children:"2023-04-17"})}),"\n",(0,i.jsx)(a.h2,{id:"de-stressing-bookingcom",children:"De-Stressing Booking.com"}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.a,{href:"https://www.alexcharlton.co/projects/booking-com-de-stresser",children:"Original"}),'.\nO escritor partilha um artigo de opini\xe3o sobre a utiliza\xe7\xe3o excessiva de t\xe1cticas de persuas\xe3o em websites de com\xe9rcio electr\xf3nico, especificamente Booking.com, e introduz a sua Extens\xe3o Cromada, "De-stresser", que remove mensagens e notifica\xe7\xf5es indutoras de stress do Booking.com, dando aos utilizadores uma experi\xeancia mais agrad\xe1vel. Ao esconder etiquetas de persuas\xe3o e linguagem de afina\xe7\xe3o para soar mais positivo, o De-stresser permite uma experi\xeancia de reserva mais calma e relaxada para os utilizadores. A extens\xe3o est\xe1 agora ao vivo e dispon\xedvel para utiliza\xe7\xe3o em Booking.com.']}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35590734",children:"Discussion Service"}),'.\nBooking.com enfrenta cr\xedticas sobre a sua utiliza\xe7\xe3o de t\xe1cticas de vendas de alta press\xe3o, incluindo mensagens urgentes e pop-ups que podem dissuadir os utilizadores. Os cr\xedticos argumentam que esta abordagem d\xe1 prioridade a m\xe9tricas de curto prazo sobre a fidelidade dos clientes a longo prazo. Os utilizadores relatam ter encontrado formas de contornar estas t\xe1cticas, incluindo a utiliza\xe7\xe3o de extens\xf5es para as bloquear ou filtrar. Entretanto, os utilizadores da Discussion Service debatem os m\xe9ritos dos testes A/B, com alguns a apontarem para o seu potencial de criar "padr\xf5es obscuros" em websites. Apesar destas preocupa\xe7\xf5es, muitos utilizadores continuam a utilizar agregadores de reservas como Booking.com e Expedia, seja por conveni\xeancia ou porque oferecem pre\xe7os favor\xe1veis e pol\xedticas de cancelamento. Alguns especialistas advertem que a reserva directa com hot\xe9is pode oferecer melhores op\xe7\xf5es de resolu\xe7\xe3o de lit\xedgios, enquanto outros assinalam que as taxas de comiss\xe3o para s\xedtios de reserva podem variar muito dependendo do hotel. No entanto, os programas de fidelidade dos hot\xe9is podem proporcionar benef\xedcios significativos aos viajantes frequentes.']}),"\n",(0,i.jsx)(a.h2,{id:"usei-difus\xe3o-est\xe1vel-e-dreambooth-para-criar-um-retrato-art\xedstico-do-meu-c\xe3o",children:"Usei Difus\xe3o Est\xe1vel e Dreambooth para criar um retrato art\xedstico do meu c\xe3o"}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.a,{href:"https://www.shruggingface.com/blog/how-i-used-stable-diffusion-and-dreambooth-to-create-a-painted-portrait-of-my-dog",children:"Original"}),".\nO artigo discute a utiliza\xe7\xe3o de t\xe9cnicas de Difus\xe3o Est\xe1vel e de IA Dreambooth para criar um retrato pintado de alta qualidade de um c\xe3o. O autor partilha todo o seu fluxo de trabalho e fornece instru\xe7\xf5es detalhadas sobre como treinar um modelo da Dreambooth em fotografias do seu c\xe3o. O artigo discute tamb\xe9m o uso de upscaling para fazer explodir pequenas imagens para impress\xf5es de alta qualidade e introduz o Stable Diffusion como um alterador de jogo para o mundo da arte generativa texto-imagem."]}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35592847",children:"Discussion Service"}),".\nUm utilizador da Discussion Service utilizou o Stable Diffusion e o Dreambooth para criar um retrato art\xedstico do seu c\xe3o, enquanto os coment\xe1rios discutiam o recuo contra a arte da IA e debates em torno dos direitos de autor e da utiliza\xe7\xe3o justa. A utiliza\xe7\xe3o de IA generativa para a arte apresenta quest\xf5es \xe9ticas relativas ao direito de autor e \xe0 utiliza\xe7\xe3o justa, com opini\xf5es divididas sobre o assunto. Alguns criticaram a Stable Diffusion por utilizar obras de arte roubadas sem compensa\xe7\xe3o como dados de forma\xe7\xe3o, enquanto outros elogiaram a tecnologia e o seu potencial para mais inova\xe7\xe3o no campo."]}),"\n",(0,i.jsx)(a.h2,{id:"att-a-modela\xe7\xe3o-do-tr\xe1fego-sem-fios-aparentemente-tornando-alguns-websites-inutiliz\xe1veis",children:"AT&T A modela\xe7\xe3o do tr\xe1fego sem fios, aparentemente tornando alguns websites inutiliz\xe1veis"}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.a,{href:"https://adriano.fyi/post/2023/2023-04-16-att-traffic-shaping-makes-websites-unusable/",children:"Original"}),'.\nO plano "ilimitado" da AT&T de 100Mbit com 50GB de dados priorizados pode ter uma forma agressiva de tr\xe1fego, fazendo com que alguns websites sejam inutiliz\xe1veis, enquanto que um teste mostrou que um cart\xe3o SIM da Verizon n\xe3o tinha o mesmo problema. O tr\xe1fego Akamai mostra provas de manipula\xe7\xe3o intencional do fluxo TCP. A modela\xe7\xe3o do tr\xe1fego afecta apenas as contas apenas de dados nas contas de empresas.']}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35592607",children:"Discussion Service"}),".\nA AT&T Wireless est\xe1 alegadamente a estrangular os endere\xe7os IP de alguns sites de transmiss\xe3o de v\xeddeo, tornando alguns sites inutiliz\xe1veis e causando discrep\xe2ncias nos testes de velocidade da Internet. Os utilizadores t\xeam sugerido solu\xe7\xf5es como a apresenta\xe7\xe3o de uma queixa da FCC, a utiliza\xe7\xe3o de uma VPN para contornar o estrangulamento, ou a tentativa de um APN diferente. Alguns comentadores s\xe3o c\xe9pticos quanto \xe0 inten\xe7\xe3o nefasta por detr\xe1s do estrangulamento, enquanto que outros prop\xf5em solu\xe7\xf5es como limites de velocidade ou a degrada\xe7\xe3o da qualidade do v\xeddeo para preservar a atribui\xe7\xe3o de dados."]}),"\n",(0,i.jsx)(a.h2,{id:"futuros-blues---emilys-cowboy-bebop-page-1999",children:"Futuros Blues - Emily's Cowboy Bebop Page (1999)"}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.a,{href:"https://futureblues.com/",children:"Original"}),".\nLamento, mas n\xe3o me \xe9 fornecido nenhum texto para resumir."]}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35589124",children:"Discussion Service"}),".\nOs utilizadores de Discussion Service expressam nostalgia pelos designs originais e criativos dos websites cl\xe1ssicos, contrastando-os com a natureza padronizada, ruidosa e monetizada dos websites modernos, sugerindo um anseio por paisagens medi\xe1ticas mais art\xedsticas e centradas na individualidade. Surgem pontos de discuss\xe3o comparando a Wikip\xe9dia e o Fandom, e a distin\xe7\xe3o entre sites m\xf3veis e apenas de desktop, e o design do website inspira nostalgia e espanto pela sua longevidade. Globalmente, o post oferece um vislumbre das mem\xf3rias carinhosas dos utilizadores da Internet primitiva e fornece uma plataforma para discutir o estado actual da web."]}),"\n",(0,i.jsx)(a.h2,{id:"lavadora-de-lou\xe7a-salm\xe3o",children:"Lavadora de lou\xe7a Salm\xe3o"}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.a,{href:"https://en.wikipedia.org/wiki/Dishwasher_salmon",children:"Original"}),".\nO salm\xe3o lavado na m\xe1quina de lavar lou\xe7a \xe9 um prato de peixe feito embrulhando peda\xe7os de salm\xe3o em pelo menos duas camadas de folha de alum\xednio e colocando-o numa m\xe1quina de lavar lou\xe7a durante o ciclo de lavagem e secagem. O m\xe9todo foi demonstrado pela primeira vez nos EUA por Vincent Price em 1975 e, desde ent\xe3o, tem sido apresentado em v\xe1rios meios de comunica\xe7\xe3o social. Contudo, existem preocupa\xe7\xf5es quanto \xe0 consist\xeancia das temperaturas nas m\xe1quinas de lavar loi\xe7a, o que pode levar a uma cozedura incompleta e a potenciais riscos para a sa\xfade."]}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35586683",children:"Discussion Service"}),".\nUm artigo do Hacker News sobre cozinhar salm\xe3o numa m\xe1quina de lavar loi\xe7a desencadeia um debate sobre a seguran\xe7a do m\xe9todo de cozedura, com os utilizadores na ind\xfastria da seguran\xe7a alimentar a contrariar as alega\xe7\xf5es feitas numa investiga\xe7\xe3o do YouTuber. Enquanto a seguran\xe7a da cozedura na m\xe1quina de lavar lou\xe7a depende de m\xfaltiplos factores, \xe9 necess\xe1rio pelo menos 63\xb0C durante 15 segundos para matar as bact\xe9rias do salm\xe3o."]}),"\n",(0,i.jsx)(a.h2,{id:"pico3d-open-world-3d-game-engine-for-the-picosystem-rp2040-microcontrolador",children:"Pico3D: Open World 3D Game Engine for the PicoSystem (RP2040 Microcontrolador)"}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.a,{href:"https://github.com/bernhardstrobl/Pico3D",children:"Original"}),".\nO motor de jogo Pico3D utiliza o segundo n\xfacleo do RP2040 como um rasterizador/GPU dedicado para executar um jogo completo em 3D de mundo aberto num microcontrolador de $1. O motor cont\xe9m uma pequena cidade e periferia com zombies shootable, com tutoriais Blender dispon\xedveis para a cria\xe7\xe3o de mundos de jogo. A simula\xe7\xe3o do motor inclui actualmente 50 NPCs e 50 zombies ao mesmo tempo, com renderiza\xe7\xe3o optimizada com a dist\xe2ncia e o abate da frustra\xe7\xe3o de visualiza\xe7\xe3o."]}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35589172",children:"Discussion Service"}),".\nUm novo motor de jogo 3D chamado Pico3D foi desenvolvido para o microcontrolador RP2040 com um ecr\xe3 de 120x120px, e falta-lhe mem\xf3ria e mem\xf3ria de v\xeddeo RAM suficiente, mas tem uma API unificada. Os hackers est\xe3o entusiasmados com formas criativas de utilizar o Pico/RP2040, e a aplica\xe7\xe3o \xfanica de chips RAM no buffer de frames faz com que este artigo se destaque no site t\xe9cnico."]}),"\n",(0,i.jsx)(a.h2,{id:"wayback-servi\xe7o-de-arquivo-auto-hospedado-integrado-com-o-arquivo-da-internet",children:"Wayback: Servi\xe7o de arquivo auto-hospedado integrado com o Arquivo da Internet"}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.a,{href:"https://github.com/wabarc/wayback",children:"Original"}),".\nWayback \xe9 uma ferramenta de arquivo auto-hospedada que visa fotografar p\xe1ginas web em c\xe1psulas de tempo. \xc9 gratuito, de c\xf3digo aberto, multiplataforma, e permite uma integra\xe7\xe3o mais f\xe1cil com v\xe1rias plataformas, incluindo o Internet Archive, archive.today, IPFS, e Telegraph. Tamb\xe9m fornece v\xe1rias op\xe7\xf5es de instala\xe7\xe3o, incluindo via GitHub, Snapcraft, APT, RPM, e Homebrew."]}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35586845",children:"Discussion Service"}),'.\nO servi\xe7o de arquivo auto-hospedado da Wabarc captura instant\xe2neos de p\xe1ginas web em "c\xe1psulas de tempo" e armazena ficheiros para uso offline; contudo, os utilizadores do Discussion Service criticam a falta de clareza do README e a falta de documenta\xe7\xe3o. Outros projectos semelhantes incluem ArchiveBox, Shiori, DiskerNet, e SingleFile; a HTTrack Website Copier \xe9 recomendada para descarregar localmente um website inteiro, enquanto a Browsertrix/Brozzler rasteja com navegadores sem cabe\xe7a para maior precis\xe3o. Um utilizador Discussion Service recomenda The Old Net para navegar em browsers antigos/modernos sem JS, e o repo linked precisa de mais clareza sobre a comparabilidade e os padr\xf5es de arquivo estabelecidos.']}),"\n",(0,i.jsx)(a.h2,{id:"a-biblioteca-de-composi\xe7\xe3o-matem\xe1tica-mais-r\xe1pida-para-a-web",children:"A biblioteca de composi\xe7\xe3o matem\xe1tica mais r\xe1pida para a web"}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.a,{href:"https://katex.org/",children:"Original"}),".\nKaTeX \xe9 uma biblioteca r\xe1pida de composi\xe7\xe3o matem\xe1tica para a web que oferece um layout de qualidade de impress\xe3o baseado em Donald Knuth's TeX, n\xe3o tem depend\xeancias, e pode ser facilmente agrupada com recursos do website para renderiza\xe7\xe3o do lado do servidor usando o Node.js. A sua API simples torna eficientemente express\xf5es matem\xe1ticas, mesmo em p\xe1ginas com m\xfaltiplas express\xf5es, sem limita\xe7\xe3o de browser ou ambiente, e \xe9 de c\xf3digo aberto sob a licen\xe7a MIT."]}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35588985",children:"Discussion Service"}),".\nKaTeX, a biblioteca de composi\xe7\xe3o matem\xe1tica mais r\xe1pida para a web, carece de suporte para diagramas, tornando-a inadequada para alguns matem\xe1ticos, enquanto que MathJax e AsciiMath t\xeam ambos projectos semelhantes. Um site de compara\xe7\xe3o foi partilhado, e o desempenho e a praticidade de adaptar a marca\xe7\xe3o a contextos diferentes est\xe1 a ser debatido pelos utilizadores do Hacker News."]}),"\n",(0,i.jsx)(a.h2,{id:"\xe1lgebra-para-ningu\xe9m-falha-em-s\xe3o-francisco",children:"'\xc1lgebra para ningu\xe9m' falha em S\xe3o Francisco"}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.a,{href:"https://www.joannejacobs.com/post/algebra-for-none-fails-in-san-francisco",children:"Original"}),'.\nA pol\xedtica "\xc1lgebra para ningu\xe9m" do distrito escolar de S\xe3o Francisco Unificado n\xe3o conseguiu melhorar os resultados dos alunos negros e hisp\xe2nicos em matem\xe1tica avan\xe7ada, de acordo com um estudo realizado por professores de Stanford, resultando num fosso de resultados cada vez maior. A decis\xe3o de adiar a \xe1lgebra at\xe9 ao nono ano e colocar alunos de baixo e alto rendimento nas mesmas turmas n\xe3o ajudou os alunos de baixo rendimento e tornou mais dif\xedcil o sucesso dos alunos de alto rendimento. As fam\xedlias que podem pagar viraram-se para cursos em linha ou escolas privadas. Um grupo de pais intentou uma ac\xe7\xe3o judicial contra o distrito, alegando que esta viola a lei estatal sobre o acesso equitativo \xe0 matem\xe1tica avan\xe7ada.']}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35595026",children:"Discussion Service"}),".\nA pol\xedtica de S\xe3o Francisco de adiar a \xe1lgebra at\xe9 ao 9\xba ano e de colocar alunos de baixo, m\xe9dio e alto rendimento nas mesmas turmas tem sido criticada, com algumas sugest\xf5es de conceitos fundamentais de matem\xe1tica a serem ensinados mais cedo. Alguns utilizadores de Discussion Service sugerem incentivar o sucesso acad\xe9mico e extracurricular ligando-o \xe0 recompensa financeira, enquanto outros argumentam que subsidiar o ensino superior atrav\xe9s de sistemas de cr\xe9dito para pagar a faculdade mais tarde seria uma solu\xe7\xe3o melhor. H\xe1 debates sobre a utilidade da educa\xe7\xe3o matem\xe1tica tradicional e a efic\xe1cia de aumentar o financiamento para reduzir o tamanho das turmas, com alguns utilizadores a sugerirem o ensino da matem\xe1tica atrav\xe9s de problemas de engenharia e os benef\xedcios da educa\xe7\xe3o em linha."]}),"\n",(0,i.jsx)(a.h2,{id:"fsf-slams-google-over-droppping-jpeg-xl-em-cromo",children:"FSF Slams Google over Droppping JPEG-XL em Cromo"}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.a,{href:"https://www.phoronix.com/news/FSF-Slams-Google-JPEG-XL",children:"Original"}),'.\nA Free Software Foundation critica a decis\xe3o da Google de abandonar o suporte JPEG-XL no Chrome, salientando a necessidade de escolha do browser e formatos de media livres. Apesar da agita\xe7\xe3o da comunidade, os engenheiros da Google continuaram com a decis\xe3o, que continua a ser uma das quest\xf5es "estreladas" de topo na hist\xf3ria do projecto Chromium. Os utilizadores demonstraram um forte apoio ao JPEG-XL, mas o foco da Google no controlo da liberdade parece prevalecer.']}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35589179",children:"Discussion Service"}),".\nA Google enfrenta cr\xedticas da Free Software Foundation por descontinuar o apoio ao JPEG-XL em Cromo apesar da sua adop\xe7\xe3o pelos principais editores de imagem. Alguns utilizadores argumentam que formatos mais antigos como PNG e JPEG s\xe3o suficientes, enquanto outros preferem codecs como AVIF para v\xeddeo. O debate centra-se em torno da viabilidade e adop\xe7\xe3o de novos formatos de imagem no ecossistema, com o apoio e interesse da ind\xfastria no JPEG-XL notado, mas a adop\xe7\xe3o depende de todos os principais navegadores que o suportam."]})]})}function l(e={}){const{wrapper:a}={...(0,r.R)(),...e.components};return a?(0,i.jsx)(a,{...e,children:(0,i.jsx)(m,{...e})}):m(e)}}}]);